INSERT INTO "papers" VALUES('10.1016/j.anucene.2026.112710','A Hybrid Fast Gauss Transform algorithm for Doppler Broadening of neutron cross section at extremely high temperatures','초고온에서 중성자 단면적 도플러 확장을 위한 하이브리드 고속 가우스 변환 알고리즘','Annals of Nuclear Energy','0306-4549','','2026-08-12','','','연구논문','원자로물리·해석','','','https://doi.org/10.1016/j.anucene.2026.112710','https://doi.org/10.1016/j.anucene.2026.112710',0,'2026-08-16','2026-08-30','active','Crossref + publisher metadata','CN','CN','OpenAlex authorship institutions');
