INSERT INTO "papers" VALUES('10.1016/j.net.2026.104654','Modeling and decoupler design for the OTSG feedwater control system of small modular reactors','소형모듈원자로 OTSG 급수제어계통의 모델링 및 비연성화기 설계','Nuclear Engineering and Technology','1738-5733','','2026-08-11','','','연구논문','설계·운전·경제','','','https://doi.org/10.1016/j.net.2026.104654','https://doi.org/10.1016/j.net.2026.104654',1,'2026-08-16','2026-08-30','active','Crossref + publisher metadata','','','OpenAlex authorship institutions');
