INSERT INTO "papers" VALUES('10.1016/j.net.2026.104644','Uncertainty analysis for nuclear design parameters of VHTR-350','VHTR-350 핵설계 변수의 불확실성 분석','Nuclear Engineering and Technology','1738-5733','','2026-08-11','','','연구논문','설계·운전·경제','','','https://doi.org/10.1016/j.net.2026.104644','https://doi.org/10.1016/j.net.2026.104644',1,'2026-08-16','2026-08-30','active','Crossref + publisher metadata','','','OpenAlex authorship institutions');
INSERT INTO "papers" VALUES('10.1016/j.pnucene.2026.106560','Application of artificial neural networks in the identification of nuclear power plant accident and transient','원자력발전소 사고 및 과도상태 식별에 대한 인공신경망 적용','Progress in Nuclear Energy','0149-1970','','2026-08-11','','','연구논문','안전·사고·리스크','','','https://doi.org/10.1016/j.pnucene.2026.106560','https://doi.org/10.1016/j.pnucene.2026.106560',0,'2026-08-16','2026-08-30','active','Crossref + publisher metadata','','','OpenAlex authorship institutions');
INSERT INTO "papers" VALUES('10.1016/j.anucene.2026.112706','A parametric review of saturated pool boiling heat transfer over vertical tubes and tube bundles for passive residual heat removal systems','피동잔열제거계통을 위한 수직관 및 관다발 포화 풀비등 열전달의 매개변수별 고찰','Annals of Nuclear Energy','0306-4549','','2026-08-10','','','리뷰·관점','열수력·유체','','','https://doi.org/10.1016/j.anucene.2026.112706','https://doi.org/10.1016/j.anucene.2026.112706',0,'2026-08-16','2026-08-30','active','Crossref + publisher metadata','IN','IN','OpenAlex authorship institutions');
