INSERT INTO "papers" VALUES('10.1016/j.anucene.2026.112728','Precise location of failed fuel assembly in operating PWR-core based on fine nuclide evolution and deep metric learning','정밀 핵종 변화 및 심층 거리학습 기반 운전 중 PWR 노심 결함 핵연료집합체 위치 정밀 탐지','Annals of Nuclear Energy','0306-4549','','2026-08-09','','','연구논문','안전·사고·리스크','','','https://doi.org/10.1016/j.anucene.2026.112728','https://doi.org/10.1016/j.anucene.2026.112728',0,'2026-08-16','2026-08-30','active','Crossref + publisher metadata','CN','CN','OpenAlex authorship institutions');
