INSERT INTO "papers" VALUES('10.1016/j.net.2026.104643','Heterogeneity in community acceptance of urban SMR siting: A contingent valuation and latent class analysis','도심 SMR 부지선정에 대한 지역사회 수용성의 이질성: 조건부가치평가 및 잠재계층 분석','Nuclear Engineering and Technology','1738-5733','','2026-08-09','','','연구논문','기타 원자력','','','https://doi.org/10.1016/j.net.2026.104643','https://doi.org/10.1016/j.net.2026.104643',1,'2026-08-16','2026-08-30','active','Crossref + publisher metadata','','','OpenAlex authorship institutions');
INSERT INTO "papers" VALUES('10.1016/j.pnucene.2026.106550','Multi-objective optimization and thermodynamic limits of free-piston Stirling generators using physics-informed active learning','물리정보 능동학습을 이용한 자유피스톤 스털링 발전기의 다목적 최적화 및 열역학적 한계','Progress in Nuclear Energy','0149-1970','','2026-08-09','','','연구논문','AI·디지털','','','https://doi.org/10.1016/j.pnucene.2026.106550','https://doi.org/10.1016/j.pnucene.2026.106550',0,'2026-08-16','2026-08-30','active','Crossref + publisher metadata','','','OpenAlex authorship institutions');
