INSERT INTO "papers" VALUES('10.1016/j.anucene.2026.112707','Diffusion-based phase space nodal method (PSN): Solving the neutron transport equation with a diffusion code','확산 기반 위상공간 노달 방법(PSN): 확산 코드를 이용한 중성자 수송방정식 풀이','Annals of Nuclear Energy','0306-4549','','2026-08-08','','','연구논문','원자로물리·해석','','','https://doi.org/10.1016/j.anucene.2026.112707','https://doi.org/10.1016/j.anucene.2026.112707',0,'2026-08-16','2026-08-30','active','Crossref + publisher metadata','CN','CN','OpenAlex authorship institutions');
INSERT INTO "papers" VALUES('10.1016/j.anucene.2026.112705','Numerical study of a guide shell for enhancing steam–air condensation heat transfer outside a straight tube','직관 외부 증기-공기 응축 열전달 향상을 위한 가이드 쉘의 수치해석 연구','Annals of Nuclear Energy','0306-4549','','2026-08-08','','','연구논문','열수력·유체','','','https://doi.org/10.1016/j.anucene.2026.112705','https://doi.org/10.1016/j.anucene.2026.112705',0,'2026-08-16','2026-08-30','active','Crossref + publisher metadata','CN','CN','OpenAlex authorship institutions');
INSERT INTO "papers" VALUES('10.1016/j.nucengdes.2026.115153','Study on vibration reduction mechanism of steam generator tube stabilizers based on damping control','감쇠 제어 기반 증기발생기 전열관 안정화기의 진동 저감 메커니즘 연구','Nuclear Engineering and Design','0029-5493','','2026-08-08','','','연구논문','기타 원자력','','','https://doi.org/10.1016/j.nucengdes.2026.115153','https://doi.org/10.1016/j.nucengdes.2026.115153',0,'2026-08-16','2026-08-30','active','Crossref + publisher metadata','CN','CN','OpenAlex authorship institutions');
