INSERT INTO "papers" VALUES('10.1016/j.pnucene.2026.106559','Tailored potassium-alumino-borosilicate glasses for high-level immobilization of Cs+, Co2+, and Ni2+: Enhancing structural integrity, thermal and mechanical stability, and leaching resistance','Cs+, Co2+ 및 Ni2+의 고함량 고정화를 위한 맞춤형 칼륨-알루미노-붕규산염 유리: 구조적 건전성, 열적·기계적 안정성 및 침출 저항성 향상','Progress in Nuclear Energy','0149-1970','','2026-08-08','','','연구논문','열수력·유체','','','https://doi.org/10.1016/j.pnucene.2026.106559','https://doi.org/10.1016/j.pnucene.2026.106559',0,'2026-08-16','2026-08-30','active','Crossref + publisher metadata','SA;EG','EG','OpenAlex authorship institutions');
